package com.agriconnect.analytics;import io.micrometer.core.instrument.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.stereotype.Component;@Component class OperationalMetrics{private final JdbcClient db;OperationalMetrics(JdbcClient d,MeterRegistry registry){db=d;Gauge.builder("agriconnect.analytics.processed_events",this,x->x.count("select count(*) from processed_events")).tag("service","analytics-service").register(registry);Gauge.builder("agriconnect.analytics.backfills_incomplete",this,x->x.count("select count(*) from backfill_checkpoints where completed=false")).tag("service","analytics-service").register(registry);}double count(String sql){try{return db.sql(sql).query(Long.class).single();}catch(Exception e){return Double.NaN;}}}
